<div class="linea-row amortizacion-linea"><div class="row">
<div class="form-group col-md-2"><label>Identificador *</label><input name="lineas[{{ $indice }}][identificador]" class="form-control" required value="{{ $linea['identificador'] ?? '' }}" placeholder="Línea {{ $indice + 1 }}"></div>
<div class="form-group col-md-2"><label>Monto *</label><input name="lineas[{{ $indice }}][monto]" type="number" step="0.01" min="0.01" class="form-control linea-monto" required value="{{ $linea['monto'] ?? '' }}"></div>
<div class="form-group col-md-1"><label>Tasa % *</label><input name="lineas[{{ $indice }}][tasa_anual]" type="number" step="0.000001" min="0" max="100" class="form-control" required value="{{ $linea['tasa_anual'] ?? '' }}"></div>
<div class="form-group col-md-1"><label>Plazo *</label><input name="lineas[{{ $indice }}][plazo_meses]" type="number" min="1" max="600" class="form-control" required value="{{ $linea['plazo_meses'] ?? 24 }}"></div>
<div class="form-group col-md-1"><label>Cuotas *</label><input name="lineas[{{ $indice }}][numero_cuotas]" type="number" min="1" max="600" class="form-control" required value="{{ $linea['numero_cuotas'] ?? 24 }}"></div>
<div class="form-group col-md-2"><label>Primer pago *</label><input name="lineas[{{ $indice }}][fecha_primer_pago]" type="date" class="form-control" required value="{{ $linea['fecha_primer_pago'] ?? date('Y-m-d', strtotime('+1 month')) }}"></div>
<div class="form-group col-md-1"><label>Método *</label><select name="lineas[{{ $indice }}][metodo]" class="form-control" required><option value="frances" {{ ($linea['metodo'] ?? 'frances') === 'frances' ? 'selected' : '' }}>Francés</option><option value="aleman" {{ ($linea['metodo'] ?? '') === 'aleman' ? 'selected' : '' }}>Alemán</option></select></div>
<div class="form-group col-md-1"><label>Seguro</label><select name="lineas[{{ $indice }}][seguro_tipo]" class="form-control"><option value="ninguno" {{ ($linea['seguro_tipo'] ?? 'ninguno') === 'ninguno' ? 'selected' : '' }}>No</option><option value="porcentaje_saldo" {{ ($linea['seguro_tipo'] ?? '') === 'porcentaje_saldo' ? 'selected' : '' }}>%</option><option value="fijo" {{ ($linea['seguro_tipo'] ?? '') === 'fijo' ? 'selected' : '' }}>Fijo</option></select></div>
<div class="form-group col-md-1"><label>Valor</label><input name="lineas[{{ $indice }}][seguro_valor]" type="number" step="0.000001" min="0" class="form-control" value="{{ $linea['seguro_valor'] ?? 0 }}"></div>
<div class="col-md-12 text-right"><button type="button" class="btn btn-danger btn-xs quitar-linea"><i class="fa fa-trash"></i> Quitar línea</button></div>
</div></div>
